{
    public AccountCreateDtoValidator()
    {
        RuleFor(x => x)
            .Must(x => x.AccountType != "Savings" || x.StartingDeposit >= 100)
            .WithMessage("Savings accounts require a minimum $100 starting deposit.");
    }
}

public WithdrawResult Withdraw(int accountId, decimal amount)
{
    var account = _repository.GetById(accountId);
    if (account.Balance < amount)
        return WithdrawResult.Fail("Insufficient funds.");

    account.Balance -= amount;
    _repository.Update(account);
    return WithdrawResult.Ok();
}

